import {
  useI18n,
  Alert,
  Button,
  Field,
  FieldDescription,
  FieldError,
  FieldLabel,
  Input,
  OtpInput,
  cn,
} from '@gntik-ai/ui';
import { useEffect, useState, type ReactNode } from 'react';
import { AuthHeader, authFormClass, useAsyncSubmit } from '../shared';

export type MfaMethod = 'code' | 'backup';

export interface MfaChallengeLabels {
  eyebrow: string;
  title: string;
  backupTitle: string;
  backupDescription: string;
  destinationDescription: (length: number, destination: string) => string;
  description: (length: number) => string;
  formLabel: string;
  codeLabel: string;
  codeRequired: (length: number) => string;
  backupLabel: string;
  backupPlaceholder: string;
  backupHint: string;
  backupRequired: string;
  submit: string;
  useCode: string;
  resendIn: (remaining: number) => string;
  resend: string;
  resent: string;
  backToSignIn: string;
  fallbackError: string;
}

export interface MfaChallengeProps {
  labels?: Partial<MfaChallengeLabels>;
  /** Verifies the code. A returned promise shows the loading state; a rejection shows in the alert. */
  onVerify?: (code: string, method: MfaMethod) => void | Promise<void>;
  /** Sends a new code; the resend button then waits `resendCooldown` seconds. */
  onResend?: () => void | Promise<void>;
  /** Seconds between resends. */
  resendCooldown?: number;
  /** Seconds left before the first resend (a code was just sent). Defaults to `resendCooldown`. */
  initialCooldown?: number;
  /** Code length. */
  length?: 6 | 8;
  /** Where the code was sent, e.g. "a•••@example.com". Omit for authenticator apps. */
  destination?: string;
  error?: string | null;
  loading?: boolean;
  /** Called when the user gives up ("Back to sign in"). */
  onCancel?: () => void;
  eyebrow?: ReactNode;
  title?: ReactNode;
  className?: string;
}

/**
 * Second-factor step: a one-time code (auto-submits when complete), a switch to a backup code,
 * and a resend button with a countdown.
 */
export function MfaChallenge({
  labels,
  onVerify,
  onResend,
  resendCooldown = 30,
  initialCooldown,
  length = 6,
  destination,
  error: errorProp,
  loading: loadingProp,
  onCancel,
  eyebrow: eyebrowProp,
  title: titleProp,
  className,
}: MfaChallengeProps) {
  const { t } = useI18n();
  const eyebrow = eyebrowProp === undefined ? (labels?.eyebrow ?? t('mfaChallenge.eyebrow')) : eyebrowProp;
  const title = titleProp === undefined ? (labels?.title ?? t('mfaChallenge.title')) : titleProp;
  const [method, setMethod] = useState<MfaMethod>('code');
  const [code, setCode] = useState('');
  const [backup, setBackup] = useState('');
  const [submitted, setSubmitted] = useState(false);
  // One start time for both, so the first render shows the full cooldown (not cooldown + 1s).
  const [start] = useState(() => Date.now());
  const [now, setNow] = useState(start);
  const [resendAt, setResendAt] = useState(() => start + (initialCooldown ?? resendCooldown) * 1000);
  const [resent, setResent] = useState(false);
  const { loading, error, run } = useAsyncSubmit(labels?.fallbackError ?? t('mfaChallenge.fallbackError'));
  const busy = loadingProp ?? loading;
  const alert = errorProp ?? error;
  const remaining = Math.max(0, Math.ceil((resendAt - now) / 1000));
  const value = method === 'code' ? code : backup.trim();
  const invalid = submitted && (method === 'code' ? code.length < length : backup.trim() === '');

  useEffect(() => {
    if (remaining <= 0) return;
    const id = window.setInterval(() => setNow(Date.now()), 1000);
    return () => window.clearInterval(id);
  }, [remaining]);

  const verify = (v: string) => {
    setSubmitted(true);
    if (method === 'code' ? v.length < length : v === '') return;
    void run(() => onVerify?.(v, method));
  };

  const resend = async () => {
    const time = Date.now();
    setNow(time);
    setResendAt(time + resendCooldown * 1000);
    setResent(true);
    await onResend?.();
  };

  const description =
    method === 'backup'
      ? (labels?.backupDescription ?? t('mfaChallenge.backupDescription'))
      : destination
        ? (labels?.destinationDescription?.(length, destination) ??
          t('mfaChallenge.destinationDescription', { length, destination }))
        : (labels?.description?.(length) ?? t('mfaChallenge.description', { length }));

  return (
    <div className={cn(authFormClass, className)}>
      <AuthHeader
        eyebrow={eyebrow}
        title={method === 'backup' ? (labels?.backupTitle ?? t('mfaChallenge.backupTitle')) : title}
        description={description}
      />
      <form
        noValidate
        aria-label={labels?.formLabel ?? t('mfaChallenge.formLabel')}
        className="flex flex-col gap-5"
        onSubmit={(e) => {
          e.preventDefault();
          verify(value);
        }}
      >
        {alert && <Alert tone="destructive" description={alert} />}
        {method === 'code' ? (
          <Field invalid={invalid}>
            <FieldLabel>{labels?.codeLabel ?? t('mfaChallenge.codeLabel')}</FieldLabel>
            <OtpInput
              length={length}
              value={code}
              onValueChange={setCode}
              onComplete={verify}
              invalid={invalid}
              groupSize={length / 2}
              disabled={busy}
            />
            <FieldError match={invalid}>
              {labels?.codeRequired?.(length) ?? t('mfaChallenge.codeRequired', { length })}
            </FieldError>
          </Field>
        ) : (
          <Field invalid={invalid}>
            <FieldLabel>{labels?.backupLabel ?? t('mfaChallenge.backupLabel')}</FieldLabel>
            <Input
              value={backup}
              onValueChange={setBackup}
              placeholder={labels?.backupPlaceholder ?? t('mfaChallenge.backupPlaceholder')}
              autoComplete="one-time-code"
              spellCheck={false}
              inputClassName="font-mono tracking-wider"
            />
            <FieldDescription>{labels?.backupHint ?? t('mfaChallenge.backupHint')}</FieldDescription>
            <FieldError match={invalid}>{labels?.backupRequired ?? t('mfaChallenge.backupRequired')}</FieldError>
          </Field>
        )}
        <Button type="submit" size="lg" loading={busy} className="w-full">
          {labels?.submit ?? t('mfaChallenge.submit')}
        </Button>
      </form>
      <div className="mt-6 flex flex-wrap items-center justify-between gap-3 text-[13px]">
        <Button
          variant="ghost"
          size="sm"
          aria-pressed={method === 'backup'}
          onClick={() => {
            setMethod(method === 'code' ? 'backup' : 'code');
            setSubmitted(false);
          }}
        >
          {method === 'code'
            ? (labels?.backupTitle ?? t('mfaChallenge.backupTitle'))
            : (labels?.useCode ?? t('mfaChallenge.useCode'))}
        </Button>
        {method === 'code' && onResend !== undefined && (
          <Button variant="ghost" size="sm" disabled={remaining > 0} onClick={() => void resend()}>
            {remaining > 0
              ? (labels?.resendIn?.(remaining) ?? t('mfaChallenge.resendIn', { remaining }))
              : (labels?.resend ?? t('mfaChallenge.resend'))}
          </Button>
        )}
      </div>
      <span role="status" className="sr-only">
        {resent ? (labels?.resent ?? t('mfaChallenge.resent')) : ''}
      </span>
      {onCancel && (
        <p className="mt-6 text-center">
          <Button variant="ghost" size="sm" onClick={onCancel}>
            {labels?.backToSignIn ?? t('mfaChallenge.backToSignIn')}
          </Button>
        </p>
      )}
    </div>
  );
}

import { cn, en, useI18n, type I18n } from '@gntik-ai/ui';
import { useState, type ReactNode } from 'react';

export interface AuthHeaderProps {
  eyebrow?: ReactNode;
  title: ReactNode;
  description?: ReactNode;
  /** Defaults to h1. `null` omits the title heading. */
  headingLevel?: 'h1' | 'h2' | 'h3' | null;
  className?: string;
}

/** Eyebrow + title + supporting line used at the top of every auth form. */
export function AuthHeader({ eyebrow, title, description, headingLevel: Heading = 'h1', className }: AuthHeaderProps) {
  return (
    <div className={cn('mb-6', className)}>
      {eyebrow != null && (
        <p className="mb-2.5 font-mono text-[11px] tracking-[0.2em] text-primary-text uppercase">{eyebrow}</p>
      )}
      {Heading != null && title != null && (
        <Heading className="text-[24px] font-semibold tracking-tight text-balance text-foreground sm:text-[27px]">
          {title}
        </Heading>
      )}
      {description != null && (
        <p className="mt-2 text-[14px] leading-relaxed text-pretty text-muted-foreground">{description}</p>
      )}
    </div>
  );
}

/** Horizontal rule with a centred caption ("Or continue with"). */
export function AuthDivider({ children }: { children: ReactNode }) {
  return (
    <div className="my-6 flex items-center gap-3" role="presentation">
      <span className="h-px flex-1 bg-border" />
      <span className="font-mono text-[10.5px] font-semibold tracking-[0.2em] text-muted-foreground uppercase">
        {children}
      </span>
      <span className="h-px flex-1 bg-border" />
    </div>
  );
}

export const authFormClass = 'w-full max-w-[392px]';

/** Loading + error state around an async submit handler. A rejection's message becomes the error. */
export function useAsyncSubmit(fallbackError?: string) {
  const { t } = useI18n();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const run = async (fn: () => void | Promise<void>) => {
    setError(null);
    setLoading(true);
    try {
      await fn();
      setLoading(false);
      return true;
    } catch (e) {
      setLoading(false);
      setError(e instanceof Error ? e.message : (fallbackError ?? t('authValidation.fallbackError')));
      return false;
    }
  };
  return { loading, error, setError, run };
}

export const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/** Email by default; text mode supports a username or username-or-email identifier. */
export interface AuthIdentifierConfig {
  type?: 'email' | 'text';
  autoComplete?: string;
  label?: ReactNode;
  help?: ReactNode;
  /** Optional stable id for the FieldDescription. Otherwise Base UI generates it. */
  helpId?: string;
  placeholder?: string;
  minLength?: number;
  maxLength?: number;
}

/** Kit-owned inline validation; consumers supply copy rather than running a second validator. */
export interface AuthValidationMessages {
  identifierRequired?: string;
  identifierInvalid?: string;
  identifierTooShort?: string;
  passwordRequired?: string;
}

/** Server errors use only these props plus the form's error alert; inline validation stays in the kit. */
export interface AuthFormAccessibilityProps {
  fieldInvalid?: { identifier?: boolean; password?: boolean };
  /** Id of the server alert (or an external feedback element), appended to flagged inputs. */
  feedbackId?: string;
  /** Describes the form itself; does not replace the per-field feedback association. */
  'aria-describedby'?: string;
  'aria-label'?: string;
  'aria-labelledby'?: string;
}

export function authIdentifierError(
  value: string,
  config?: AuthIdentifierConfig,
  messages?: AuthValidationMessages,
  t?: I18n['t'],
  labels?: AuthValidationMessages,
) {
  const trimmed = value.trim();
  const fallback =
    config?.type === 'text'
      ? (t?.('authValidation.identifierInvalid') ?? en['authValidation.identifierInvalid'])
      : (t?.('authValidation.emailInvalid') ?? en['authValidation.emailInvalid']);
  if (!trimmed) return messages?.identifierRequired ?? labels?.identifierRequired ?? fallback;
  if (config?.minLength !== undefined && trimmed.length < config.minLength)
    return (
      messages?.identifierTooShort ??
      messages?.identifierInvalid ??
      labels?.identifierTooShort ??
      labels?.identifierInvalid ??
      fallback
    );
  if (
    ((config?.type ?? 'email') === 'email' && !EMAIL_RE.test(trimmed)) ||
    (config?.maxLength !== undefined && trimmed.length > config.maxLength)
  )
    return messages?.identifierInvalid ?? labels?.identifierInvalid ?? fallback;
  return null;
}

/** Ordered text/email fields collected before the sign-up password. Ids must be unique. */
export interface AuthSignUpField {
  id: string;
  label: string;
  placeholder?: string;
  help?: ReactNode;
  required?: boolean;
  type?: 'text' | 'email';
  autoComplete?: string;
  /** Consumer copy for kit-owned validation. */
  messages?: { required?: string; invalid?: string };
}

export interface AuthSignUpFieldLabels {
  fieldRequired: (label: string) => string;
  fieldInvalid: string;
}

export function authSignUpFieldError(
  value: string,
  field: AuthSignUpField,
  t?: I18n['t'],
  labels?: Partial<AuthSignUpFieldLabels>,
) {
  const trimmed = value.trim();
  if (!trimmed)
    return field.required
      ? (field.messages?.required ??
          labels?.fieldRequired?.(field.label) ??
          t?.('authValidation.fieldRequired', { label: field.label }) ??
          en['authValidation.fieldRequired'].replace('{label}', () => field.label))
      : null;
  if (field.type === 'email' && !EMAIL_RE.test(trimmed))
    return (
      field.messages?.invalid ??
      labels?.fieldInvalid ??
      t?.('authValidation.emailInvalid') ??
      en['authValidation.emailInvalid']
    );
  return null;
}

/** Consumer-owned copy and optional action when account creation is unavailable. */
export interface AuthUnavailableState {
  title: ReactNode;
  message: ReactNode;
  action?: ReactNode;
}

/** Kit-owned sign-up validation with consumer-owned copy. */
export interface AuthSignUpValidationMessages {
  passwordTooShort?: (minimum: number) => string;
  termsRequired?: string;
}
